/*=----------------------------------------------------------------------=*\
   Use :Sent to a component to allow dynamic amendment of the interrupts for a component
       :
       :Parameters for macro Ev_AddInterrupts:
       :  HandlerCode[20] : Text to amend for all component interrupts
       :
       :Returns : Non-zero to block code insertion
\*=----------------------------------------------------------------------=*/
MX_UINT32 FCM_Ev_AddInterrupts(MX_CHAR *FCL_HANDLERCODE, MX_UINT16 FCLsz_HANDLERCODE)
{
  //Local variable definitions
  #define FCLsz_ISR_MACRO 20
  MX_CHAR FCL_ISR_MACRO[FCLsz_ISR_MACRO] = "";
  #define FCLsz_UART_STR 20
  MX_CHAR FCL_UART_STR[FCLsz_UART_STR] = "";
  MX_UINT32 FCR_RETVAL; // Non-zero to block code insertion


  // Simulation
  // .ISR_Macro=::Expand.MacroBody("Uart_isr", this, 0)

  // Calculation
  {
  MX_CHAR FCI_TMP_STR[MX_MAX_TMPSTR_SIZE];
  FCI_SHEAD("MX_UART_INT_CH",15, FCI_ITOS32(001, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE),20, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE);
  FCI_SHEAD(FCI_TMP_STR,MX_MAX_TMPSTR_SIZE, "_FUNC\n\n",8, FCL_UART_STR,20);
  FCI_SHEAD(FCL_UART_STR,FCLsz_UART_STR, "MX_UINT8 FCL_RX;\n\n",19, FCL_UART_STR,20);
  FCI_SHEAD(FCL_UART_STR,FCLsz_UART_STR, "if (MX_UART_INT_CH",19, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE);
  FCI_SHEAD(FCI_TMP_STR,MX_MAX_TMPSTR_SIZE, FCI_ITOS32(001, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE),20, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE);
  FCI_SHEAD(FCI_TMP_STR,MX_MAX_TMPSTR_SIZE, "_DET)\n{\n\n",10, FCL_UART_STR,20);
  }

  // Calculation
  FCI_SHEAD(FCL_UART_STR,FCLsz_UART_STR, FCL_ISR_MACRO,FCLsz_ISR_MACRO, FCL_ISR_MACRO,20);

  // Calculation
  {
  MX_CHAR FCI_TMP_STR[MX_MAX_TMPSTR_SIZE];
  FCI_SHEAD(FCL_ISR_MACRO,FCLsz_ISR_MACRO, "MX_UART_INT_CH",15, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE);
  FCI_SHEAD(FCI_TMP_STR,MX_MAX_TMPSTR_SIZE, FCI_ITOS32(001, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE),20, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE);
  FCI_SHEAD(FCI_TMP_STR,MX_MAX_TMPSTR_SIZE, "_CLR;",6, FCL_ISR_MACRO,20);
  FCI_SHEAD(FCL_ISR_MACRO,FCLsz_ISR_MACRO, "\n\n}\n\nMX_UART_INT_FUNC_END\n",27, FCL_ISR_MACRO,20);
  }

  // Calculation
  {
  MX_CHAR FCI_TMP_STR[MX_MAX_TMPSTR_SIZE];
  FCI_SHEAD(FCL_HANDLERCODE,FCLsz_HANDLERCODE, "\n\n",3, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE);
  FCI_SHEAD(FCI_TMP_STR,MX_MAX_TMPSTR_SIZE, FCL_ISR_MACRO,FCLsz_ISR_MACRO, FCL_HANDLERCODE,20);
  }

  // Calculation
  FCR_RETVAL = 0;

  return (FCR_RETVAL);

  //Local variable definitions
  #undef FCLsz_ISR_MACRO
  #undef FCLsz_UART_STR
}

