/*=----------------------------------------------------------------------=*\
   Use :Scan and return a list of all responsive servos. 
       :Returns number of servos found.
       :
       :Parameters for macro ListServos:
       :  ServoList[20] : Array to store found servo IDs
       :  MaxCount : Max number of servos to try and return. 0=Don't limit
       :
       :Returns : Number of servos found
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_ListServos(MX_UINT8 *FCL_SERVOLIST, MX_UINT16 FCLsz_SERVOLIST, MX_UINT8 FCL_MAXCOUNT)
{
  //Local variable definitions
  MX_UINT8 FCL_SERVOID = (0x0); // Current servo ID being tested
  MX_BOOL FCL_FOUND = (0); // Whether current servo responded
  MX_UINT8 FCR_RETVAL; // Number of servos found


  // Initialize count
  FCR_RETVAL = 0;

  // Scan all possible servo IDs
  while (FCL_SERVOID < 254)
  {
    // Ping servo
    FCL_FOUND = FCM_PingServo(FCL_SERVOID);

    // If servo responded
    if (FCL_FOUND)
    {    

      // Add to list
      FCL_SERVOLIST[FCR_RETVAL] = FCL_SERVOID;
      FCR_RETVAL = FCR_RETVAL + 1;

      // Decision
      if (FCR_RETVAL == FCL_MAXCOUNT)
      {      

        // End Loop
        FCL_SERVOID = 253;

      // } else {

      }

    // } else {

    }

    // Next servo ID
    FCL_SERVOID = FCL_SERVOID + 1;

  }

  return (FCR_RETVAL);

}

/*=----------------------------------------------------------------------=*\
   Use :Read current position of servo. Returns position in steps (0-4095).
       :
       :Parameters for macro ReadPosition:
       :  ServoID : Servo ID
       :
       :Returns : Position in steps (0-4095), or -1 if error
\*=----------------------------------------------------------------------=*/
MX_SINT16 FCM_ReadPosition(MX_UINT8 FCL_SERVOID)
{
  //Local variable definitions
  MX_UINT16 FCL_RAWPOSITION = (0x0); // Raw 16-bit position value
  MX_SINT16 FCR_RETVAL; // Position in steps (0-4095), or -1 if error


  // Store register address
  FCV_PACKETBUFFER[0] = FCV_ST3215_ADDR_CURRENT_POS;
  FCV_PACKETBUFFER[1] = 2;

  // Send read packet
  FCM_Prv_SendPacket(FCL_SERVOID, FCV_ST3215_CMD_READ, 2);

  // Receive response
  FCM_Prv_ReceiveResponse(100);

  // Check if response received
  if (FCV_RESPONSELENGTH >= 2)
  {  

    // Combine bytes - Python library sts_makeword uses data[0] as low byte, data[1] as high byte. Our ResponseBuffer[2] appears to be high byte, ResponseBuffer[3] is low byte, so swap them.
    FCL_RAWPOSITION = FCV_RESPONSEBUFFER[3] + (FCV_RESPONSEBUFFER[2] << 8);

    // Mask to 12 bits (0-4095) as per ST3215 specification
    FCR_RETVAL = FCL_RAWPOSITION & 0x0FFF;

  } else {

    // Return error value
    FCR_RETVAL = -1;

  }

  return (FCR_RETVAL);

}

