/*=----------------------------------------------------------------------=*\
   Use :Rotate servo continuously in specified direction. Speed range: 50-1000. Direction: 0=forward, 1=reverse.
       :
       :Parameters for macro Rotate:
       :  ServoID : Servo ID
       :  Speed : Rotation speed (50-1000)
       :  Direction : Direction: 0=forward, 1=reverse
       :
       :Returns : True if successful
\*=----------------------------------------------------------------------=*/
MX_BOOL FCM_Rotate(MX_UINT8 FCL_SERVOID, MX_UINT16 FCL_SPEED, MX_UINT8 FCL_DIRECTION)
{
  //Local variable definitions
  MX_UINT16 FCL_SPEEDWITHDIRECTION = (0x0); // Speed value with direction bit
  MX_BOOL FCL_MODERESULT = (0); // Result of setting mode
  MX_BOOL FCR_RETVAL; // True if successful


  // Set mode to constant speed mode first
  FCV_PACKETBUFFER[0] = FCV_ST3215_ADDR_MODE;
  FCV_PACKETBUFFER[1] = FCV_ST3215_MODE_SPEED;

  // Send write packet to mode register
  FCM_Prv_SendPacket(FCL_SERVOID, FCV_ST3215_CMD_WRITE, 2);

  // Receive response for mode set
  FCL_MODERESULT = FCM_Prv_ReceiveResponse(100);

  // Set speed with direction bit (BIT10 = direction)
  FCL_SPEEDWITHDIRECTION = FCL_SPEED;
  FCL_SPEEDWITHDIRECTION = FCL_SPEEDWITHDIRECTION + (FCL_DIRECTION << 10);

  // Store register address and speed bytes with direction
  FCV_PACKETBUFFER[0] = FCV_ST3215_ADDR_SPEED;
  FCV_PACKETBUFFER[1] = FCL_SPEEDWITHDIRECTION;
  FCV_PACKETBUFFER[2] = FCL_SPEEDWITHDIRECTION >> 8;

  // Send write packet to speed register
  FCM_Prv_SendPacket(FCL_SERVOID, FCV_ST3215_CMD_WRITE, 3);

  // Receive and verify response
  FCR_RETVAL = FCM_Prv_ReceiveResponse(100);

  return (FCR_RETVAL);

}

