/*=----------------------------------------------------------------------=*\
   Use :Receive response packet from servo
       :
       :Parameters for macro Prv_ReceiveResponse:
       :  Timeout : Timeout in milliseconds
       :
       :Returns : True if valid response received
\*=----------------------------------------------------------------------=*/
MX_BOOL FCM_Prv_ReceiveResponse(MX_UINT16 FCL_TIMEOUT)
{
  //Local variable definitions
  MX_UINT8 FCL_HEADER1 = (0x0); // First header byte
  MX_UINT8 FCL_HEADER2 = (0x0); // Second header byte
  MX_UINT8 FCL_IDX = (0x0); // Loop index
  MX_UINT16 FCL_TIMEOUTCOUNT = (0x0); // Timeout counter
  MX_BOOL FCR_RETVAL; // True if valid response received


  // Initialize response length
  FCV_RESPONSELENGTH = 0;
  FCR_RETVAL = 0;

  // Wait for header byte 1
  while ((FCL_HEADER1 != FCV_ST3215_HEADER1) && (FCL_TIMEOUTCOUNT < FCL_TIMEOUT))
  {
    // Decision
    if (FCD_01211_CircularBuffer1__GetNumberBytes())
    {    

      // Check for received byte
      FCL_HEADER1 = FCD_01211_CircularBuffer1__GetByte();

    } else {

      // Delay
      FCI_DELAYBYTE_MS(1);

      // Increment timeout
      FCL_TIMEOUTCOUNT = FCL_TIMEOUTCOUNT + 1;

    }

  }

  // Check if header 1 received
  if (FCL_HEADER1 == FCV_ST3215_HEADER1)
  {  

    // Wait for header byte 2
    while ((FCL_HEADER2 == 0) && (FCL_TIMEOUTCOUNT < FCL_TIMEOUT))
    {
      // Decision
      if (FCD_01211_CircularBuffer1__GetNumberBytes() >= 3)
      {      

        // Check for received byte
        FCL_HEADER2 = FCD_01211_CircularBuffer1__GetByte();

      } else {

        // Delay
        FCI_DELAYBYTE_MS(1);

        // Increment timeout
        FCL_TIMEOUTCOUNT = FCL_TIMEOUTCOUNT + 1;

      }

    }

    // Check if header 2 is correct
    if (FCL_HEADER2 == FCV_ST3215_HEADER2)
    {    

      // Receive ID
      FCV_RESPONSEBUFFER[0] = FCD_01211_CircularBuffer1__GetByte();

      // Receive Length
      FCV_RESPONSEBUFFER[1] = FCD_01211_CircularBuffer1__GetByte();

      // Calculate number of data bytes
      FCV_RESPONSELENGTH = FCV_RESPONSEBUFFER[1] - 2;

      // Receive all data bytes
      while (FCL_IDX < FCV_RESPONSELENGTH)
      {
        // Decision
        if (FCD_01211_CircularBuffer1__GetNumberBytes() >= 3)
        {        

          // Receive Length
          FCV_RESPONSEBUFFER[FCL_IDX + 2] = FCD_01211_CircularBuffer1__GetByte();

          // Increment index
          FCL_IDX = FCL_IDX + 1;

          // Decision
          if (FCL_IDX > 17)
          {          

            // Goto Connection Point
            goto FCC_Prv_ReceiveResponse_A;

          // } else {

          }

        } else {

          // Delay
          FCI_DELAYBYTE_MS(1);

          // Increment timeout
          FCL_TIMEOUTCOUNT = FCL_TIMEOUTCOUNT + 1;

        }

      }

      // Mark as successful
      FCR_RETVAL = 1;

      // Declare Connection Point
    FCC_Prv_ReceiveResponse_A:
      ;

    // } else {

    }

  // } else {

  }

  return (FCR_RETVAL);

}

