/*=----------------------------------------------------------------------=*\
   Use :Move servo to a target angle. Angle range: -180 to 180 degrees.
       :
       :Parameters for macro MoveToAngle:
       :  ServoID : Servo ID
       :  Angle : Angle range: -180 to 180 degrees.
       :
       :Returns : True if successful
\*=----------------------------------------------------------------------=*/
MX_BOOL FCM_MoveToAngle(MX_UINT8 FCL_SERVOID, MX_FLOAT FCL_ANGLE)
{
  //Local variable definitions
  MX_UINT16 FCL_POSITION = (0x0);
  MX_BOOL FCR_RETVAL; // True if successful


  // Convert angle to step position
  FCL_ANGLE = flt_add(FCL_ANGLE, 180.0);
  FCL_ANGLE = flt_mul(FCL_ANGLE, 11.37777);
  FCL_POSITION = flt_toi(FCL_ANGLE);
  FCL_POSITION = FCL_POSITION & 0x0FFF;

  // User Macro
  FCR_RETVAL = FCM_MoveTo(FCL_SERVOID, FCL_POSITION);

  return (FCR_RETVAL);

}

/*=----------------------------------------------------------------------=*\
   Use :Lock EEPROM to prevent writes from being saved after power loss. IMPORTANT: Use the NEW servo ID after ChangeID.
       :
       :Parameters for macro LockEEPROM:
       :  ServoID : Servo ID (use NEW ID after ChangeID)
       :
       :Returns : True if successful
\*=----------------------------------------------------------------------=*/
MX_BOOL FCM_LockEEPROM(MX_UINT8 FCL_SERVOID)
{
  //Local variable definitions
  MX_BOOL FCR_RETVAL; // True if successful


  // Store register address and lock value (1 = lock, 0 = unlock)
  FCV_PACKETBUFFER[0] = FCV_ST3215_ADDR_LOCK;
  FCV_PACKETBUFFER[1] = 1;

  // Send write packet
  FCM_Prv_SendPacket(FCL_SERVOID, FCV_ST3215_CMD_WRITE, 2);

  // Receive and verify response
  FCR_RETVAL = FCM_Prv_ReceiveResponse(200);

  // If successful, wait for EEPROM lock to take effect (2 seconds required)
  if (FCR_RETVAL)
  {  

    // Delay for EEPROM lock to take effect - ST3215 requires 2 seconds
    FCI_DELAYINT_MS(2000);

  // } else {

  }

  return (FCR_RETVAL);

}

