/*=----------------------------------------------------------------------=*\
   Use :Send an STS protocol packet to the servo
       :
       :Parameters for macro Prv_SendPacket:
       :  ServoID : Servo ID (0-253)
       :  Instruction : Instruction byte
       :  ParamCount : Number of parameter bytes
       :
       :Returns : True if successful
\*=----------------------------------------------------------------------=*/
MX_BOOL FCM_Prv_SendPacket(MX_UINT8 FCL_SERVOID, MX_UINT8 FCL_INSTRUCTION, MX_UINT8 FCL_PARAMCOUNT)
{
  //Local variable definitions
  MX_UINT8 FCL_LENGTH = (0x0); // Packet length
  MX_UINT8 FCL_CHECKSUM = (0x0); // Calculated checksum
  MX_UINT8 FCL_IDX = (0x0); // Loop index
  MX_BOOL FCR_RETVAL; // True if successful


  // Calculate packet length (parameters + 2)
  FCL_LENGTH = FCL_PARAMCOUNT + 2;

  // Calculate checksum
  FCL_CHECKSUM = FCM_Prv_CalculateChecksum(FCL_SERVOID, FCL_LENGTH, FCL_INSTRUCTION, FCL_PARAMCOUNT);

  // Send header byte 1
  FC_CAL_UART_Send_1(FCV_ST3215_HEADER1);

  // Send header byte 2
  FC_CAL_UART_Send_1(FCV_ST3215_HEADER2);

  // Send servo ID
  FC_CAL_UART_Send_1(FCL_SERVOID);

  // Send length
  FC_CAL_UART_Send_1(FCL_LENGTH);

  // Send instruction
  FC_CAL_UART_Send_1(FCL_INSTRUCTION);

  // Send all parameter bytes
  while (FCL_IDX < FCL_PARAMCOUNT)
  {
    // Send parameter byte
    FC_CAL_UART_Send_1(FCV_PACKETBUFFER[FCL_IDX]);

    // Increment index
    FCL_IDX = FCL_IDX + 1;

  }

  // Send checksum
  FC_CAL_UART_Send_1(FCL_CHECKSUM);

  // Component Macro
  FCD_01211_CircularBuffer1__FlushBuffer();

  // Return success
  FCR_RETVAL = 1;

  return (FCR_RETVAL);

}

