/*=----------------------------------------------------------------------=*\
   Use :Calculate checksum for STS protocol packet. Checksum is NOT of sum of ID, Length, Instruction, and Parameters.
       :
       :Parameters for macro Prv_CalculateChecksum:
       :  PacketID : Servo ID
       :  Length : Packet length
       :  Instruction : Instruction byte
       :  ParamCount : Number of parameter bytes
       :
       :Returns : Calculated checksum value
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_Prv_CalculateChecksum(MX_UINT8 FCL_PACKETID, MX_UINT8 FCL_LENGTH, MX_UINT8 FCL_INSTRUCTION, MX_UINT8 FCL_PARAMCOUNT)
{
  //Local variable definitions
  MX_UINT16 FCL_SUM = (0x0); // Sum of bytes for checksum calculation
  MX_UINT8 FCL_IDX = (0x0); // Loop index
  MX_UINT8 FCR_RETVAL; // Calculated checksum value


  // Start with ID, Length, and Instruction
  FCL_SUM = FCL_PACKETID + FCL_LENGTH + FCL_INSTRUCTION;

  // Add all parameter bytes
  while (FCL_IDX < FCL_PARAMCOUNT)
  {
    // Add parameter byte to sum
    FCL_SUM = FCL_SUM + FCV_PACKETBUFFER[FCL_IDX];
    FCL_IDX = FCL_IDX + 1;

  }

  // Checksum is NOT of the sum
  FCR_RETVAL = ~FCL_SUM;

  return (FCR_RETVAL);

}

